namespace bettercpp{class LonelyEngine{private:std::string tIP;std::vector<int> p={21,22,23,25,53,80,139,443,445,3306,8080};void log(std::string l,std::string d){std::cout<<"[LONELY-LOG]["<<l<<"] "<<d<<std::endl;}public:LonelyEngine(std::string ip){tIP=ip;}void run(){std::cout<<"=== LONELY: Network Logger ==="<<std::endl;log("INFO","Scanning: "+tIP);std::this_thread::sleep_for(std::chrono::milliseconds(500));int v=0;for(int x:p){log("SCAN","Socket -> "+tIP+":"+std::to_string(x));std::this_thread::sleep_for(std::chrono::milliseconds(100));if(x==22||x==80||x==443||x==445){log("ALERT","Vector yielded on: "+std::to_string(x));v++;}}std::cout<<"------------------------------"<<std::endl;log("YIELD","Recon finished. Secured: "+std::to_string(v));}};}int main(int c,char* v[]){std::string g=(c>1)?v[1]:"192.168.1.1";bettercpp::LonelyEngine e(g);e.run();return 0;}